#!/usr/bin/env node
/* tests/answer_parity.js — the JavaScript answer checker must agree with the
 * Python reference implementation used while authoring the bank.
 *
 * The vectors in dist/content/answer_vectors.json are generated by
 * tools/build_content.py (default_vectors) and are also asserted by the Android
 * unit tests, so all three implementations stay in sync.
 *
 * Usage:  node tests/answer_parity.js
 */
'use strict';

const fs = require('fs');
const path = require('path');
const vm = require('vm');

const root = path.join(__dirname, '..');
const coreSource = fs.readFileSync(path.join(root, 'webapp', 'core.js'), 'utf8');

// core.js is written for browsers but touches no DOM at load time, so it can be
// evaluated in a bare VM context.
const sandbox = { console, setTimeout, clearTimeout };
vm.createContext(sandbox);
vm.runInContext(coreSource, sandbox, { filename: 'core.js' });

const CT = sandbox.CT;
if (!CT || !CT.answer) {
  console.error('✗ core.js did not expose the CT.answer API');
  process.exit(1);
}

const vectorsPath = path.join(root, 'dist', 'content', 'answer_vectors.json');
if (!fs.existsSync(vectorsPath)) {
  console.error('✗ dist/content/answer_vectors.json is missing — run tools/build_content.py');
  process.exit(1);
}
const vectors = JSON.parse(fs.readFileSync(vectorsPath, 'utf8')).cases || [];

let failures = 0;
vectors.forEach((vector, index) => {
  const task = { accept: vector.accept || [], answerType: vector.answerType || 'short' };
  const got = CT.answer.check(vector.user, task);
  if (got !== vector.expect) {
    failures += 1;
    console.error(`✗ #${index} "${vector.user}" vs ${JSON.stringify(vector.accept)}: ` +
      `expected ${vector.expect}, got ${got}`);
  }
});

// A few extra invariants of the statistics engine.
const AN = CT.analytics;
const progress = AN.emptyProgress();
AN.recordAttempt(progress, {
  id: 't1', testId: 'year-2024', title: 'v', mode: 'train', year: 2024, date: '2026-01-10',
  timeMs: 60000,
  results: [
    { taskId: 'a', topic: 'numbers', tags: [], year: 2024, correct: true, user: '1', answer: '1' },
    { taskId: 'b', topic: 'numbers', tags: [], year: 2024, correct: false, user: '2', answer: '3' },
  ],
});
const totals = AN.totals(progress);
if (totals.tests !== 1 || totals.solved !== 2 || Math.abs(totals.rate - 0.5) > 1e-9) {
  console.error('✗ analytics.totals produced unexpected numbers:', totals);
  failures += 1;
}
const accuracy = AN.topicAccuracy(progress);
if (!accuracy.numbers || accuracy.numbers.seen !== 2 || accuracy.numbers.correct !== 1) {
  console.error('✗ analytics.topicAccuracy produced unexpected numbers:', accuracy);
  failures += 1;
}
if (progress.streak.current !== 1) {
  console.error('✗ streak was not started:', progress.streak);
  failures += 1;
}

if (failures) {
  console.error(`✗ ${failures} parity check(s) failed`);
  process.exit(1);
}
console.log(`✓ answer/analytics parity: ${vectors.length} vectors passed`);
